import{_ as n,a0 as p,w as a,s as i,ao as u,I as l,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"埃隆·馬斯克開源推特算法的計劃存在缺陷 | LCTT x X-CMD","titleTemplate":false,"description":"埃隆·馬斯克開源推特算法的計劃存在缺陷 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"埃隆·馬斯克開源推特算法的計劃存在缺陷 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"埃隆·馬斯克開源推特算法的計劃存在缺陷 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220428 Elon Musk’s Plan To Open Source The Twitter Algorithm Has Flaws","title":"埃隆·馬斯克開源推特算法的計劃存在缺陷","tag":"202205","desc":""},"relativePath":"202205/20220428 Elon Musk’s Plan To Open Source The Twitter Algorithm Has Flaws.md","filePath":"[post].md"}'),m={name:"202205/20220428 Elon Musk’s Plan To Open Source The Twitter Algorithm Has Flaws.md"};function T(d,t,w,f,h,g){const o=p("Link");return a(),i("div",null,[t[15]||(t[15]=u('<h1 id="埃隆·馬斯克開源推特算法的計劃存在缺陷" tabindex="-1">埃隆·馬斯克開源推特算法的計劃存在缺陷 <a class="header-anchor" href="#埃隆·馬斯克開源推特算法的計劃存在缺陷" aria-label="Permalink to “埃隆·馬斯克開源推特算法的計劃存在缺陷”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/twiiter-696x392.jpg" alt="推特"></p><p>報道稱，在推特確認接受收購請求的幾個小時後，埃隆·馬斯克就明確表示了他對推特的期望。馬斯克在一份新聞稿中羅列了他計劃做出的重大改變，包括開源“決定用户在推流中看到什麼”的算法。</p><p>馬斯克希望開源推特的算法，是因為他長期以來一直擔心該平台有可能進行政治壓制。但老實説，即便開源，也不可能達到他的預期效果。專家們擔心，這可能反而帶來一連串意想不到的問題。</p><p>雖然馬斯克對權威深惡痛絕，但是他對算法開源的野心和世界各地立法者的願望不謀而合。近年來，許多政府都將這一原則作為打擊大科技公司的基石。</p><p>英國社交媒體監管機構 Ofcom 的首席執行官 Melanie Dawes 曾表示，社交媒體公司應當解釋其代碼的運作方式。此外，歐盟新近通過的《<ruby>數字服務法案<rt>Digital Services Act</rt></ruby>（DSA）》於 4 月 23 日獲得批准，該法案將責成平台提供更多的公開性。2022 年 2 月，美國的民主黨參議員提交了《<ruby>算法問責法案<rt>Algorithmic Accountability Act</rt></ruby>（AAA）》的立法申請。這些法案的目標是加強算法的透明度和監督，包括我們在社交媒體上的“<ruby>時間軸<rt>timeline</rt></ruby>”和“<ruby>新聞流<rt>news feed</rt></ruby>”以及我們生活的其他方面。</p><p>允許競爭者看到並修改推特的算法，可能意味着有人會偷取源代碼，並提供一個改名的版本。互聯網的許多部分都運行在開源軟件上，其中最著名的就是 OpenSSL，這是一個被大量在線使用的安全工具包，而它在 2014 年被黑客攻擊了。</p><p>還有一些已經創建的開源社交網絡。Mastodon 是一個微博網絡，為回應對 Twitter 主導地位的擔憂而創建。它允許用户檢查其代碼，這些代碼可在 GitHub 軟件倉庫中找到。</p><p>然而，閲讀一個算法背後的代碼，並不總能告訴你它的工作方式，而且對於大部分普通人來説，它也提供不了足夠的關於公司組織架構以及開發流程的信息。</p><p>Jonathan Gray 是倫敦國王學院/關鍵基礎設施研究的高級講師，他説：“這有點像只用遺傳物質來理解古代生物。是的，它能告訴我們的信息比任何方式都多，但如果説我們因此瞭解它們的生活方式，那就太誇張了。”</p><p>推特同樣也不是由單一算法控制的。Catherine Flick 是英國德蒙福特大學/研究計算和社會責任的研究員，她説：“其中一些會決定人們在他們的“時間軸”上看到什麼趨勢、內容或者推薦關注的人。調節用户“時間軸”上顯示哪些信息的算法，將會是人們最感興趣的。然而，即使如此，如果缺少訓練數據，單純開源算法也沒多大用處。”</p><p>Cobbe 認為，開源推特算法的危害大於好處。因為計算機代碼並沒有透露算法是如何開發或評估的：有哪些元素或考慮、在這個過程中的優先級是什麼等等。所以開源可能不會使推特的透明度發生重大變化。反而，它可能會帶來嚴重的安全隱患。</p><hr>',13)),l("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/04/elon-musks-plan-to-open-source-the-twitter-algorithm-has-flaws/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/04/elon-musks-plan-to-open-source-the-twitter-algorithm-has-flaws/",-1)])]),_:1})]),l("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const k=n(m,[["render",T]]);export{C as __pageData,k as default};
